/bin/zsh -lc "node --input-type=module -e '
import { chromium } from \"@playwright/test\";
const browser = await chromium.launch({ headless: true });
const results = [];
const errors = [];
for (const viewport of [{width:360,height:800},{width:390,height:844},{width:430,height:932}]) {
  const page = await browser.newPage({ viewport });
  page.on(\"console\", message => { if (message.type() === \"error\") errors.push(message.text()); });
  page.on(\"pageerror\", error => errors.push(error.message));
  await page.goto(\"http://127.0.0.1:5173/\", { waitUntil: \"networkidle\" });
  await page.locator(\"canvas\").waitFor({ state: \"visible\" });
  const before = await page.evaluate(() => window.__GAME_TEST__.resetGame().player.y);
  await page.keyboard.down(\"ArrowUp\");
  await page.waitForTimeout(450);
  await page.keyboard.up(\"ArrowUp\");
  const probe = await page.evaluate(() => ({
    keys: Object.keys(window.__GAME_TEST__),
    afterY: window.__GAME_TEST__.getState().player.y,
    bodyWidth: document.body.scrollWidth,
    viewportWidth: window.innerWidth,
    canvas: Boolean(document.querySelector(\"canvas\")),
    title: document.querySelector(\"h1\")?.textContent,
  }));
  results.push({ viewport, movedUp: probe.afterY < before, ...probe });
  if (viewport.width === 390) await page.screenshot({ path: \"/tmp/pawshop-smoke.png\", fullPage: true });
  await page.close();
}
await browser.close();
console.log(JSON.stringify({ results, errors }, null, 2));
'"

