import { readdir, readFile } from \"node:fs/promises\";
import { BuildReportSchema } from \"../../../../src/schemas/index.ts\";
const report = BuildReportSchema.parse(JSON.parse(await readFile(\"artifacts/build-report.json\", \"utf8\")));
const walk = async (directory, prefix = \"\") => (await Promise.all((await readdir(directory, { withFileTypes: true })).map(async entry => entry.isDirectory() ? walk("'`${directory}/${entry.name}`, `${prefix}${entry.name}/`) : `${prefix}${entry.name}`))).flat().sort();
const files = await walk("dist");
if (JSON.stringify(files) !== JSON.stringify([...report.files].sort())) throw new Error(`build report mismatch: ${JSON.stringify(files)}`);
const source = await readFile("src/main.ts", "utf8");
const controls = ["resetGame", "getState", "spawnCustomer", "completeOrder", "grantCurrency", "upgradeStation", "setRandomSeed"];
if (!controls.every(name => source.includes(name))) throw new Error("missing deterministic test control");
console.log(JSON.stringify({ buildReportSchema: "pass", enumeratedFiles: files.length, deterministicControls: controls.length }));
'"'"

